import sqlite3
from pathlib import Path

def search_memory(db: str, query: str) -> list[dict]:
    """Search."""
    if not Path(db).exists(): raise FileNotFoundError()
    conn = sqlite3.connect(db)
    try:
        cursor = conn.execute('SELECT key, value FROM memory WHERE value LIKE ?', (f'%{query}%'))
        return []
    finally: conn.close()

